"""Independently written keyboard variants, not generated by the lexicon itself."""

import json
from pathlib import Path

import pytest

from smart_recycling.guidance import CHOICES, GuidanceClassifier
from smart_recycling.language import policy_text


@pytest.mark.parametrize(
    "text",
    [
        "ne e cista obleka",
        "ne e chista obleka",
        "ne nosliva obleka",
        "necista obleka",
        "valkana kosula",
        "mokra maica",
        "iskinata kosula",
    ],
)
def test_negative_latin_clothing_cannot_be_overridden(text):
    root = Path(__file__).resolve().parents[1]
    policy = json.loads((root / "data/policy/skopje_v2.json").read_text())
    classifier = GuidanceClassifier(policy, 0.85)
    assert classifier.decide(text).status == "held"
    assert classifier.decide(text, "wearable_clothes", True).status == "held"


def test_latin_aliases_preserve_boundaries_and_positive_condition():
    assert policy_text("cista obleka") == "clean clothes"
    assert policy_text("nepoznat predmet") == "nepoznat predmet"
    assert policy_text("plastichno shishe") == "plastic bottle"
    assert policy_text("plasticno sise") == "plastic bottle"


@pytest.mark.parametrize(
    "text",
    [
        "glass bottle and plastic bottle",
        "plastic bottle and newspaper",
        "стаклено шише и пластично шише",
        "stakleno shishe i plastichno shishe",
        "stakleno sise i plasticno sise",
    ],
)
def test_mixed_recyclables_cannot_be_confirmed_as_one_item(text):
    class MustNotRun:
        def suggest(self, text):
            raise AssertionError("Mixed items must be resolved before ML suggestions")

    root = Path(__file__).resolve().parents[1]
    policy = json.loads((root / "data/policy/skopje_v2.json").read_text())
    classifier = GuidanceClassifier(policy, 0.85, category_suggester=MustNotRun())
    assert classifier.decide(text).status == "held"
    for kind in CHOICES:
        answer = classifier.decide(text, kind, True)
        assert answer.status in {"held", "specialist"}
        assert not answer.facility_ids
    # The user can recover by describing and confirming each item separately.
    for item, kind in [
        ("glass bottle", "empty_glass_packaging"),
        ("plastic bottle", "empty_plastic_bottle"),
    ]:
        assert classifier.decide(item, kind, True).status == "ready_for_site_matching"
